/*
 * A376843  Numbers k such that Omega(k + Omega(k)) = Omega(k) +
 *          Omega(Omega(k)), where Omega = A001222.
 * https://oeis.org/A376843
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 28, u16 n <= 7852, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   bigomega
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* a(n) is the nth integer k such that
   Omega(k + Omega(k)) = Omega(k) + Omega(Omega(k))   (OEIS A376843) */
/* The sequence is generated by a simple incremental search and cached across calls. */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/bigomega.h"   /* bigomega(idx_t n) returns Omega(n) as seq_t */

static seq_t *cache = NULL;          /* dynamically growing array of sequence terms */
static size_t cached = 0;            /* number of terms stored in cache */
static size_t cap = 0;               /* current capacity of the cache */
static idx_t last_k = 0;             /* last integer examined */

static void ensure_capacity(size_t needed, size_t *cap, void **ptr, size_t elem_size)
{
    if (needed <= *cap) return;
    size_t new_cap = (*cap == 0) ? 16 : *cap * 2;
    while (new_cap < needed) new_cap *= 2;
    /* realloc is allowed in C++17 as a C function and C11 is fine */
    void *tmp = realloc(*ptr, new_cap * elem_size);
    *ptr = tmp;
    *cap = new_cap;
}

seq_t a(idx_t n)
{
    if (n == 0) return 0; /* undefined below offset, return 0 for safety */

    /* Expand the cache until we have at least n terms */
    while (cached < n) {
        last_k++;                           /* next integer to test */
        seq_t Omega_k = bigomega(last_k);   /* Omega(k) */

        /* Omega(Omega(k)) -- if Omega(k)==0, define as 0 */
        seq_t Omega_Omega_k = (Omega_k == 0) ? 0 : bigomega((idx_t)Omega_k);

        /* k + Omega(k), need cast for addition */
        idx_t sum = last_k + (idx_t)Omega_k;
        seq_t Omega_sum = bigomega(sum);    /* Omega(k + Omega(k)) */

        if (Omega_sum == Omega_k + Omega_Omega_k) {
            ensure_capacity(cached + 1, &cap, (void **)&cache, sizeof(seq_t));
            cache[cached++] = last_k;
        }
    }
    return cache[n - 1];
}
